/* The governor's state crises as storylines (rules only, no React).
   A crisis no longer happens once and vanishes: each is a story of a few
   years in one LGA ({l} in the text), told on the storyline engine
   (storylines.js): programmes, bills to the House of Assembly, executive
   orders a State High Court can strike down, and weak answers that boil
   over. Costs are ₦B; fx in the state's own units (app points; sec, hp,
   agr, lit, infra, cor as fractions; pStab points); dz moves the mood of
   the crisis's zone. All people are fictional. */

const P = (id, l, x) => ({ id, kind: "programme", l, ...x });
const B = (id, l, nm, pass, fail, x) => ({ id, kind: "bill", l, bill: { nm, pass, fail }, cost: .1, ...x });
const O = (id, l, nm, next, risk, struck, x) => ({ id, kind: "order", l, next, order: { nm, risk, struck }, cost: .05, ...x });
const A = (id, l, x) => ({ id, kind: "act", l, ...x });
// Two openings each: a new game draws one, so the same crisis does not begin the same way twice.
const story = (id, nm, beats, boil, extra = {}) => ({ id: "state_" + id, nm, start: "a", starts: beats.a2 ? ["a", "a2"] : undefined, boil, heat0: 50, drift: 0, scale: .05, beats, ...extra });

