export const STATE_STORY_IDS = Object.keys(STATE_STORIES);
// Fill a card's text with the place: {l} is the LGA where the story happens.
export const placeText = (x, l) => typeof x === "string" ? x.replace(/\{l\}/g, l) : Array.isArray(x) ? x.map(v => placeText(v, l)) : x && typeof x === "object" ? Object.fromEntries(Object.entries(x).map(([k, v]) => [k, placeText(v, l)])) : x;
